import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel for fused division + LeakyReLU
fused_div_leakyrelu_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_div_leakyrelu_kernel(const float* __restrict__ in,
                                           float* __restrict__ out,
                                           float divisor,
                                           float negative_slope,
                                           int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = in[idx] / divisor;
        if (val < 0.f) {
            val = val * negative_slope;
        }
        out[idx] = val;
    }
}

torch::Tensor fused_div_leakyrelu_cuda(torch::Tensor input,
                                       float divisor,
                                       float negative_slope) {
    auto size = input.numel();
    auto out = torch::zeros_like(input);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    fused_div_leakyrelu_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        out.data_ptr<float>(),
        divisor,
        negative_slope,
        size
    );

    return out;
}
"""

fused_div_leakyrelu_cpp_source = r"""
torch::Tensor fused_div_leakyrelu_cuda(torch::Tensor input,
                                       float divisor,
                                       float negative_slope);
"""

# Build the custom operator
fused_div_leakyrelu = load_inline(
    name="fused_div_leakyrelu",
    cpp_sources=fused_div_leakyrelu_cpp_source,
    cuda_sources=fused_div_leakyrelu_source,
    functions=["fused_div_leakyrelu_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model that performs a convolution, then fuses division and LeakyReLU into a custom CUDA kernel.
    """
    def __init__(self, in_channels, out_channels, kernel_size, divisor):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.divisor = divisor

    def forward(self, x):
        x = self.conv(x)
        x = fused_div_leakyrelu.fused_div_leakyrelu_cuda(x, float(self.divisor), 0.01)
        return x
